    @ApiResponse({ status: 503, description: '文件恢复校验繁忙或存储不可用，可稍后重试' })
    @ApiResponse({ status: 504, description: 'UPLOAD.VERIFICATION_TIMEOUT，恢复校验超时' })
    @Get(':uploadSessionId')
    getStatus(
    @CurrentAuth()
    auth: CurrentAuthType, 
    @Param({ schema: uploadSessionParamsSchema })
    params: UploadSessionParams) {
        return this.uploadService.getStatus(auth.userId, params.uploadSessionId);
    }
    @ApiConsumes('application/octet-stream')
    @ApiBody({
        schema: {
            type: 'string',
            format: 'binary',
        },
    })
    @HttpCode(HttpStatus.OK)
    @Put(':uploadSessionId/parts/:partNumber')
    uploadPart(
    @CurrentAuth()
    auth: CurrentAuthType, 
    @Param({ schema: uploadPartParamsSchema })
    params: UploadPartParams, 
    @Headers('content-length')
    contentLength: string | undefined, 
    @Headers('content-encoding')
    contentEncoding: string | undefined, 
    @Req()
    request: OctetStreamRequest, 
    @Res({ passthrough: true })
    reply: FastifyReply) {
        const abortController = new AbortController();
        const onAborted = () => abortController.abort();
        const onReplyClose = () => {
            if (!reply.raw.writableEnded) {
                abortController.abort();
            }
        };
        request.raw.once('aborted', onAborted);
        reply.raw.once('close', onReplyClose);
        return (this.uploadService
            .uploadPart({
            ownerId: auth.userId,
            uploadSessionId: params.uploadSessionId,
            partNumber: params.partNumber,
            contentLength,
            contentEncoding,
            body: request.body,
            abortSignal: abortController.signal,
        })
            .finally(() => {
            if (!request.body.readableEnded && !request.body.destroyed) {
                request.body.resume();
            }
            request.raw.off('aborted', onAborted);
            reply.raw.off('close', onReplyClose);
        }));
    }
    @ApiResponse({ status: 409, description: '上传状态、分片或完整对象校验不通过' })
    @ApiResponse({
        status: 503,
        description: 'UPLOAD.VERIFICATION_BUSY 或 UPLOAD.STORAGE_UNAVAILABLE，可重试',
    })
    @ApiResponse({ status: 504, description: 'UPLOAD.VERIFICATION_TIMEOUT，重试完成请求可恢复' })
    @HttpCode(HttpStatus.OK)
    @Post(':uploadSessionId/complete')
    complete(
    @CurrentAuth()
    auth: CurrentAuthType, 
    @Param({ schema: uploadSessionParamsSchema })
    params: UploadSessionParams) {
        return this.uploadService.complete(auth.userId, params.uploadSessionId);
    }
    @Delete(':uploadSessionId')
    abort(
    @CurrentAuth()
    auth: CurrentAuthType, 
    @Param({ schema: uploadSessionParamsSchema })
    params: UploadSessionParams) {
        return this.uploadService.abort(auth.userId, params.uploadSessionId);
    }
}
